import {ATTRS,CLASSES,ITEMS,SKILLS,MAPS,PET_TYPES,createGame,stats,weight,advance,command,validate,summarize,xpNeeded,petStats,fusionChance} from './engine.mjs';
import {readSave,writeSave,readLegacy,acquireSession,listArchives} from './storage.mjs';
import {WorldRenderer} from './renderer.mjs';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],modal=$('#modal'),body=$('#modalBody');
const renderer=new WorldRenderer($('#world'));
let recoveryError=null;
let S=null,revision=0,resolvedAt=Date.now(),session=null,legacy=null,mode='start',busy=false,loading=true,ready=false,background=false,saving=false,saveQueue=Promise.resolve(),lastFrame=0,lastSave=0,lastUi=0,toastUntil=0,log=[],selectedClass='knight',allocation={},bagTab='equipment',bankTab='bag',fusionChoice=null,importPending=null,sound=false,audio=null,tap=null,pendingNPC=null,offlineWorker=null;
const attrNames={STR:'力量',DEX:'敏捷',CON:'體質',WIS:'精神',CHA:'魅力',INT:'智力'};
const phaseNames={idle:'手動冒險',hunt:'自動狩獵中',heal:'城鎮恢復中',store:'整理戰利品',resupply:'購買補給中',return:'返回狩獵地圖',stopped:'狩獵已停止'};
const escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const itemName=e=>(ITEMS[e.itemId]?.name||e.itemId)+(ITEMS[e.itemId]?.kind==='equipment'?' +'+e.plus:'');
const slotName=s=>({weapon:'武器',armor:'防具',charm:'飾品'})[s]||s;
function checked(s){let r=validate(s);if(!r.ok)throw Error(r.errors.join('；'));return s}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');toastUntil=performance.now()+4500}
function messages(events){renderer.notice(events,S);for(const e of events||[]){if(['hit','miss','petHit','critical','magic','fusionStaged','fusionDuplicate'].includes(e.type))continue;if(e.message)log.push(e.message)}log=log.slice(-3);$('#messages').innerHTML=log.map(x=>'<div>'+escape(x)+'</div>').join('');if(events?.some(e=>e.type==='book'||e.type==='capture'))tone(570,.2)}
function tone(f=250,d=.1){if(!sound||document.hidden)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();let o=audio.createOscillator(),g=audio.createGain();o.type='triangle';o.frequency.value=f;g.gain.setValueAtTime(.025,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+d);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+d)}catch{}}
let importGeneration=0,importLegacyPending=null;
function cancelImport(){importGeneration++;importPending=null;importLegacyPending=null}
let musicStep=0;setInterval(()=>{if(sound&&S&&!loading&&!background&&!recoveryError){const notes=S.player.map==='town'?[146.83,174.61,220,196,174.61,130.81]:[110,130.81,146.83,164.81,146.83,130.81];tone(notes[musicStep++%notes.length],2.6)}},3200);
function loadText(t,progress){$('#loading').hidden=false;$('#loadingText').textContent=t;if(progress!=null)$('#loadingProgress').value=progress}
function finishLoading(){background=document.hidden;loading=false;$('#loading').hidden=true;lastFrame=0;lastSave=performance.now();presentImport()}
function queueSave(state=S,at=Date.now(),archive=false){if(!state)return Promise.resolve();let snapshot=structuredClone(state);checked(snapshot);saving=true;$('#saveState').textContent='儲存中';const task=saveQueue.then(async()=>{let env=await writeSave(snapshot,revision,at,{archive});revision=env.revision;resolvedAt=env.resolvedAt;return env});saveQueue=task.catch(()=>{});return task.then(v=>{saving=false;$('#saveState').textContent='已儲存';return v},e=>{saving=false;throw e})}
function fatal(error){recoveryError=error;busy=true;loading=false;$('#loading').hidden=true;offlineWorker?.terminate();show('blocked',heading('進度已保護')+`<p>${escape(error.message||error)}</p><div class="notice warn">為避免覆寫，遊戲已暫停。原有存檔沒有被重設。</div><div class="actions">${S?'<button data-do="export">匯出目前進度</button>':''}<button data-do="reload">重新載入</button></div>`,true)}
async function mutate(c,opts={}){if(!S||busy||loading)return null;busy=true;const before=structuredClone(S);try{const r=command(S,c);if(!r.ok){S=before;toast(r.error||'無法完成此操作');return r}checked(S);await queueSave();messages(r.events);update();return r}catch(e){S=before;fatal(e);return null}finally{if(!recoveryError)busy=false}}
function heading(t){return `<button class="close" data-do="close" aria-label="關閉">×</button><h2>${escape(t)}</h2>`}
function show(m,html,force=false){if(m==='offline'&&(importPending||importLegacyPending||mode==='legacy'))return;if(loading&&m!=='blocked')return;if(recoveryError&&!['blocked','export'].includes(m))return;mode=m;body.innerHTML=html;if(!modal.open)modal.showModal();if(force)body.querySelector('[data-do="close"]')?.remove()}
function close(){if(recoveryError){fatal(recoveryError);return;}if(busy)return;if(mode==='blocked')return;cancelImport();if(!S)return showStart();modal.close();mode='';fusionChoice=null;lastFrame=0}
modal.addEventListener('cancel',e=>{if(busy&&!recoveryError){e.preventDefault();return}if(recoveryError){e.preventDefault();close();return}cancelImport();if(!S||mode==='blocked'){e.preventDefault();if(mode!=='blocked')showStart()}else{mode='';fusionChoice=null}});modal.addEventListener('click',e=>{if(e.target===modal&&S&&mode!=='blocked')close()});
function defaultAllocation(id){const c=CLASSES[id],a={},order=id==='mage'?['INT','WIS','CON','DEX','CHA','STR']:id==='elf'?['DEX','CON','WIS','STR','INT','CHA']:id==='darkelf'?['DEX','STR','CON','WIS','INT','CHA']:['STR','CON','DEX','WIS','CHA','INT'];let left=c.points;for(const k of order){a[k]=Math.min(left,(id==='knight'&&k==='STR'?20:18)-c.base[k]);left-=a[k]}return a}
function showStart(){const c=CLASSES[selectedClass],spent=Object.values(allocation).reduce((a,b)=>a+b,0),left=c.points-spent;show('start',`<div class="intro"><span class="eyebrow">7DayWar</span><h1>七日戰線</h1><p>帶上行囊，回到那片熟悉的荒林。</p></div>${S?`<button class="primary" data-do="continue" style="width:100%;margin-bottom:16px">繼續 ${escape(S.player.name)} · Lv.${S.player.level}</button>`:''}<div class="classes">${Object.values(CLASSES).map(c=>`<button data-class="${c.id}" class="classCard ${selectedClass===c.id?'active':''}"><img src="art/${c.id}-portrait.webp" alt=""><strong>${c.name}</strong></button>`).join('')}</div><div class="classDesc">${c.description}<br><span class="fine">所有職業從普通攻擊開始；技能只能閱讀怪物掉落的技能書。</span></div><div class="points">剩餘配點 ${left} / ${c.points}</div><div class="attributes">${ATTRS.map(k=>`<div class="attribute"><label>${attrNames[k]}<small>${k} · 基礎 ${c.base[k]}</small></label><button data-attr="${k}" data-delta="-1" aria-label="降低${attrNames[k]}" ${(allocation[k]||0)<=0?'disabled':''}>−</button><b>${c.base[k]+(allocation[k]||0)}</b><button data-attr="${k}" data-delta="1" aria-label="提高${attrNames[k]}" ${left<=0||c.base[k]+(allocation[k]||0)>=(selectedClass==='knight'&&k==='STR'?20:18)?'disabled':''}>+</button></div>`).join('')}</div><button class="flat" data-do="recommend" style="width:100%;font-size:14px">套用建議配點</button><div class="startRow"><input id="nameInput" class="textinput" maxlength="20" placeholder="旅人的名字" aria-label="角色名字"><button class="primary" data-do="create" ${left!==0?'disabled':''}>開始新冒險</button></div><div class="actions">${legacy?'<button data-do="legacy">檢視舊版角色</button>':''}<button data-do="import">匯入備份</button></div><p class="fine" style="text-align:center">單人・本機存檔・無額外付費服務<br>新角色不會刪除舊版存檔。正式遊玩請定期匯出備份。</p>`)}
function update(){if(!S)return;let p=S.player,st=stats(S),w=weight(S);$('#heroName').textContent=p.name+' · '+CLASSES[p.classId].name;$('#heroLevel').textContent=`Lv.${p.level}　${Math.floor(p.xp)} / ${xpNeeded(p.level)} EXP`;$('#hpFill').style.width=clamp(p.hp/st.maxHp*100,0,100)+'%';$('#mpFill').style.width=clamp(p.mp/st.maxMp*100,0,100)+'%';$('#hpText').textContent=`${Math.ceil(p.hp)} / ${st.maxHp}`;$('#mpText').textContent=`${Math.floor(p.mp)} / ${st.maxMp}`;$('#xpFill').style.width=clamp(p.xp/xpNeeded(p.level)*100,0,100)+'%';$('#portraitImage').src='art/'+p.classId+'-portrait.webp';$('#goldText').textContent=p.gold.toLocaleString()+' 金幣';$('#weightText').textContent='負重 '+Math.round(w.ratio*100)+'%';$('#weightText').title=w.label;$('#mapName').textContent=MAPS[p.map].name;$('#coord').textContent=`${Math.round(p.x)}, ${Math.round(p.y)} · ${S.auto.enabled?'持續狩獵':'點地面移動'}`;$('#autoState').textContent=S.auto.enabled?(phaseNames[S.auto.phase]||'自動狩獵'):(S.auto.reason||'開啟自動狩獵');$('#autoState').classList.toggle('active',S.auto.enabled);let a=S.auto.settings;$('#hpCount').textContent=S.inventory.stacks[a.hpPotion]||0;$('#mpCount').textContent=S.inventory.stacks[a.mpPotion]||0;let skills=Object.values(SKILLS).filter(k=>k.classId===p.classId);for(let i=0;i<3;i++){let k=skills[i],known=k&&p.skills.includes(k.id),b=$(`[data-action="skill${i}"]`);b.disabled=!known;b.title=k?`${k.name} · ${known?k.mp+' MP':'尚未習得'}`:'無技能';$('#skill'+i+'Label').textContent=k?known?({blood_mana:'轉換',nature_heal:'治癒',piercing_arrow:'射擊',ember_storm:'風暴',arcane_mend:'治癒',ice_lance:'霜矛',death_mark:'印記',double_cut:'雙斬',heavy_strike:'重擊'})[k.id]||k.name:'未學':'—';b.querySelector('i').style.transform=`scaleY(${known?(p.cooldowns[k.id]||0)/k.cooldown:0})`}let enemy=S.world.monsters.find(x=>x.id===p.targetId&&x.hp>0);$('#target').hidden=!enemy;if(enemy)$('#target').innerHTML=`${escape(enemy.name)}<div class="meter"><i style="width:${clamp(enemy.hp/enemy.maxHp*100,0,100)}%"></i></div>`;let npc=p.map==='town'?MAPS.town.npcs.find(n=>distance(n,p)<150):null;$('#interact').hidden=!npc;if(npc){$('#interact').textContent='交談 · '+npc.name;$('#interact').dataset.npc=npc.id}$('#worldHint').textContent=S.auto.reason&&!S.auto.enabled?S.auto.reason:''}
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),distance=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
function showCharacter(){let p=S.player,st=stats(S),w=weight(S);show('character',heading(p.name+' · '+CLASSES[p.classId].name)+`<p>Lv.${p.level} · 經驗 ${p.xp} / ${xpNeeded(p.level)}</p><div class="stats">${[['生命',st.maxHp],['魔力',st.maxMp],['攻擊',Math.round(st.attack)],['防禦',st.ac],['魔防',st.mr],['攜重',st.carry]].map(([a,b])=>`<div class="stat"><small>${a}</small><b>${b}</b></div>`).join('')}</div><div class="attributes">${ATTRS.map(k=>`<div class="attribute"><label>${attrNames[k]}<small>${k}</small></label><b>${st.attrs[k]}</b>${p.attributePoints>0?`<button data-grow="${k}" aria-label="提高${attrNames[k]}">+</button>`:''}</div>`).join('')}</div><p>可分配成長點數：${p.attributePoints}。51 級起，每升 1 級獲得 1 點。</p><div class="notice">負重 ${Math.round(w.total)} / ${w.capacity}（${Math.round(w.ratio*100)}%）<br>${w.label}</div><p class="fine">力量：近戰／命中／負重；敏捷：遠程／命中／防禦；體質：生命成長／恢復／負重；精神：魔力成長／恢復／魔防；智力：魔法／治療；魅力：寵物容量。裝備的臨時加成不追溯生命與魔力的升級成長。</p>`)}
function showBag(tab=bagTab){bagTab=tab;let html=heading('行囊')+`<div class="tabs"><button data-bag="equipment" class="${tab==='equipment'?'active':''}">裝備</button><button data-bag="supplies" class="${tab==='supplies'?'active':''}">物品</button><button data-bag="fusion" class="${tab==='fusion'?'active':''}">融合</button></div>`;if(tab==='equipment'){html+=S.inventory.equipment.map(e=>{let it=ITEMS[e.itemId],worn=Object.values(S.equipped).includes(e.uid);return `<div class="item"><span class="icon">${it.kind==='collar'?'◉':it.slot==='weapon'?'⚔':it.slot==='armor'?'⬡':'◇'}</span><div class="desc"><strong>${escape(itemName(e))}${worn?'<span class="badge">裝備中</span>':''}${(e.count||1)>1?' × '+e.count:''}</strong><small>${it.kind==='collar'?'專屬寵物項圈，保留同一隻寵物的身分':`${slotName(it.slot)} · 重量 ${it.weight}${it.attack?' · 攻擊 '+(it.attack+e.plus*2):''}${it.ac?' · 防禦 '+(it.ac+e.plus):''}`}</small></div>${it.kind==='collar'?`<button data-panel="pets">查看</button>`:`<button data-equip="${escape(e.uid)}">${worn?'卸下':'裝備'}</button>`}</div>`}).join('')}else if(tab==='supplies'){let rows=Object.entries(S.inventory.stacks);html+=rows.length?rows.map(([id,n])=>`<div class="item"><span class="icon">${ITEMS[id].kind==='book'?'▤':ITEMS[id].kind==='potion'?'✚':'◇'}</span><div class="desc"><strong>${escape(ITEMS[id].name)} × ${n}</strong><small>單件重量 ${ITEMS[id].weight}${ITEMS[id].kind==='book'?' · 怪物掉落，手動學習':''}</small></div>${ITEMS[id].kind==='book'?`<button data-learn="${ITEMS[id].skillId}" ${SKILLS[ITEMS[id].skillId].classId!==S.player.classId||S.player.skills.includes(ITEMS[id].skillId)?'disabled':''}>學習</button>`:''}</div>`).join(''):'<p class="empty">行囊裡沒有消耗品。</p>'}else{html+=`<div class="notice warn">兩件「相同裝備、相同 +N」融合。成功變成一件 +N+1；失敗兩件都永久消失。裝備中的物品需先卸下。</div><p class="fine">本版本用融合取代強化卷軸。成功率為目前測試設定，確認前會清楚顯示。</p>`;let groups=new Map;for(let e of S.inventory.equipment){if(ITEMS[e.itemId].kind!=='equipment'||Object.values(S.equipped).includes(e.uid))continue;let k=e.itemId+':'+e.plus;if(!groups.has(k))groups.set(k,[]);groups.get(k).push(e)}html+=[...groups.values()].map(es=>{let n=es.reduce((v,e)=>v+(e.count||1),0),e=es[0];return `<div class="item"><div class="desc"><strong>${escape(itemName(e))} × ${n}</strong><small>成功率 ${Math.round(fusionChance(e.plus)*100)}%</small></div><button data-fuse="${escape(e.uid)}" ${n<2?'disabled':''}>選擇兩件</button></div>`}).join('')||'<p class="empty">還沒有可融合的備用裝備。</p>'}show('bag',html)}
function showFusion(uid){const first=S.inventory.equipment.find(e=>e.uid===uid);if(!first)return;let candidates=S.inventory.equipment.filter(e=>e.itemId===first.itemId&&e.plus===first.plus&&!Object.values(S.equipped).includes(e.uid));let ids=[];for(let e of candidates)for(let n=0;n<Math.min(e.count||1,2)&&ids.length<2;n++)ids.push(e.uid);if(ids.length<2)return toast('需要兩件相同裝備。');fusionChoice={uids:ids,itemId:first.itemId,plus:first.plus};show('fusionConfirm',heading('確認融合')+`<p style="font-size:19px;color:#d6c398">${escape(itemName(first))} × 2</p><div class="notice warn">成功率 ${Math.round(fusionChance(first.plus)*100)}%<br>成功：獲得 ${escape(ITEMS[first.itemId].name)} +${first.plus+1}<br><strong>失敗：這兩件裝備都永久消失。</strong></div><p>結果會立即儲存；重新整理不會重抽。這個操作只會手動進行，自動狩獵不會融合裝備。</p><div class="actions"><button class="danger" data-do="commitFusion">接受風險並融合</button><button data-bag="fusion">保留裝備</button></div>`)}
async function commitFusion(){if(busy||!fusionChoice)return;const choice={...fusionChoice,uids:[...fusionChoice.uids]};busy=true;const before=structuredClone(S);try{let r=command(S,{type:'fuseStage',uids:choice.uids});if(!r.ok){S=before;fusionChoice=null;toast(r.error||'材料已變動，請重新選擇。');showBag('fusion');return}await queueSave();let id=S.fusion.pending.id;let result=command(S,{type:'fuseCommit',transactionId:id});if(!result.ok)throw Error(result.error);await queueSave();let success=S.fusion.lastResult.success;messages(result.events);show('fusionResult',heading(success?'融合成功':'融合失敗')+`<div class="notice ${success?'':'warn'}">${success?`獲得 ${escape(ITEMS[choice.itemId].name)} +${choice.plus+1}`:'兩件材料已化為灰燼。'}</div><p>結果已存檔。</p><button class="primary" data-bag="fusion" style="width:100%">回到融合</button>`);fusionChoice=null;update()}catch(e){let saved=await readSave().catch(()=>null);if(saved){S=saved.state;revision=saved.revision;resolvedAt=saved.resolvedAt}else S=before;fatal(e)}finally{if(!recoveryError)busy=false}}
function showSkills(){const skills=Object.values(SKILLS).filter(k=>k.classId===S.player.classId);show('skills',heading('技能與技能書')+`<p>從普通攻擊開始。技能書只會從怪物身上掉落；取得後仍需親自閱讀。</p>${skills.map(k=>{let known=S.player.skills.includes(k.id),n=S.inventory.stacks['book_'+k.id]||0,stored=S.storage.stacks['book_'+k.id]||0;return `<div class="item"><span class="icon">${known?'✦':'▤'}</span><div class="desc"><strong>${k.name}${known?'<span class="badge">已習得</span>':''}</strong><small>${k.description}<br>${k.mp} MP · 冷卻 ${k.cooldown} 秒 · 行囊 ${n} 本 · 倉庫 ${stored} 本</small></div>${!known&&!n&&stored?`<button data-get-book="${k.id}">${S.player.map==='town'?'從倉庫取出':'回城取書'}</button>`:''}<button data-learn="${k.id}" ${known||!n?'disabled':''}>${known?'已學會':'閱讀'}</button></div>`}).join('')}<div class="notice">自動施法只使用你已學會的技能，可在自動狩獵設定關閉。</div>`)}
function showPets(){const cap=stats(S).petCapacity;show('pets',heading('寵物與專屬項圈')+`<p>出戰 ${S.pets.filter(p=>p.active).length} / ${cap}。容量＝⌊魅力 ÷ 6⌋${S.player.classId==='elf'?' + 妖精額外 2 隻':''}。</p>${S.pets.length?S.pets.map(p=>{let st=petStats(p);return `<div class="item"><img class="petArt" src="art/${p.type}-portrait.webp" alt=""><div class="desc"><strong>${escape(p.name)} · Lv.${p.level}${p.dead?'<span class="badge">等待復活</span>':p.active?'<span class="badge">出戰中</span>':''}</strong><small>HP ${Math.ceil(p.hp)} / ${st.maxHp}<br>生命資質 ${Math.round(p.aptitudes.hp*100)} · 攻擊 ${Math.round(p.aptitudes.attack*100)} · 速度 ${Math.round(p.aptitudes.speed*100)}<br>項圈 ${escape(p.collarUid)} · ${PET_TYPES[p.type].description}</small></div>${p.dead?`<button data-revive="${escape(p.id)}" ${S.player.map!=='town'?'disabled':''}>召回</button>`:`<button data-pet="${escape(p.id)}">${p.active?'休息':'出戰'}</button>`}</div>`}).join(''):'<div class="empty">還沒有同行的夥伴。<br>在森林點選野生動物，帶上牠喜歡的食物。</div>'}<div class="notice">死亡時自動使用寵物復活卷軸；沒有卷軸時回城由照護員召回，再補給返回設定地圖。項圈保留同一隻寵物的身分、等級與資質。</div>`)}
function showFeed(id){let w=S.world.wildPets.find(x=>x.id===id);if(!w)return close();const pet=PET_TYPES[w.type],food=ITEMS[pet.food];show('feed',heading(w.name)+`<img class="petArt" style="width:110px;height:110px;float:right" src="art/${w.type}-portrait.webp" alt=""><p>${pet.description}</p><p>牠喜歡 ${food.name}。每次餵食都有機會馴服，可能需要多次嘗試。</p><p class="fine">成功後獲得專屬項圈，個體資質會固定保存。沒有空位時仍可收藏，之後再選擇出戰。</p><div class="actions"><button class="primary" data-feed="${escape(id)}" data-food="${pet.food}" ${!(S.inventory.stacks[pet.food]||0)?'disabled':''}>餵 ${food.name}（${S.inventory.stacks[pet.food]||0}）</button><button data-do="close">先離開</button></div>`)}
function showMap(){show('map',heading('冒險地圖')+`<p>目前可遊玩的三個地區。較危險的地區提供較高經驗與裝備掉落機會。</p>${Object.values(MAPS).map(m=>`<div class="mapCard ${S.player.map===m.id?'current':''}"><h3>${m.name}${S.player.map===m.id?'<span class="badge">所在位置</span>':''}</h3><p>${m.description}</p><button data-travel="${m.id}" ${S.player.map===m.id?'disabled':''}>${m.id==='town'?'返回城鎮':'前往此地'}</button></div>`).join('')}<p class="fine">地區與地形是這個單人版本的原創內容；世界地圖參考不代表整片大陸都已開放。</p>`)}
function showAuto(){let a=S.auto.settings;show('auto',heading('自動狩獵與補給')+`<p>${S.auto.enabled?'目前：'+(phaseNames[S.auto.phase]||S.auto.phase):'選好地圖與攜帶數量，再開始狩獵。'}</p>${S.auto.reason?'<div class="notice warn">'+escape(S.auto.reason)+'</div>':''}<div class="formRow"><label for="autoMap">狩獵地圖</label><select id="autoMap">${Object.values(MAPS).filter(m=>m.id!=='town').map(m=>`<option value="${m.id}" ${S.auto.selectedMap===m.id?'selected':''}>${m.name}</option>`).join('')}</select></div><div class="formRow"><label for="hpType">生命藥水</label><select id="hpType">${Object.values(ITEMS).filter(i=>i.heal).map(i=>`<option value="${i.id}" ${a.hpPotion===i.id?'selected':''}>${i.name}</option>`).join('')}</select></div><div class="formRow"><label for="hpTarget">回城補到幾瓶</label><input id="hpTarget" type="number" min="0" max="10000" step="1" value="${a.hpTarget}"></div><div class="formRow"><label for="mpType">魔力藥水</label><select id="mpType">${Object.values(ITEMS).filter(i=>i.mana).map(i=>`<option value="${i.id}" ${a.mpPotion===i.id?'selected':''}>${i.name}</option>`).join('')}</select></div><div class="formRow"><label for="mpTarget">回城補到幾瓶</label><input id="mpTarget" type="number" min="0" max="10000" step="1" value="${a.mpTarget}"></div><div class="formRow"><label for="hpThreshold">生命低於幾 % 喝水</label><input id="hpThreshold" type="number" min="1" max="95" step="1" value="${Math.round(a.hpThreshold*100)}"></div><div class="formRow"><label for="mpThreshold">魔力低於幾 % 喝水</label><input id="mpThreshold" type="number" min="0" max="95" step="1" value="${Math.round(a.mpThreshold*100)}"></div><div class="formRow"><label for="autoStore">回城安全存放戰利品</label><input id="autoStore" type="checkbox" ${a.autoStore?'checked':''}></div><div class="formRow"><label for="useSkills">自動使用已習得技能</label><input id="useSkills" type="checkbox" ${a.useSkills?'checked':''}></div><div class="notice">死亡後回城、補給、返回此地。金幣不足會留在城鎮並停止。自動存放不會出售、融合或摧毀物品。</div><p class="fine">離線時間沒有領取上限；重開遊戲時計算。收益受這份存檔的裝備、地圖、技能、寵物、負重與補給影響。離線期間不會自動學技能或融合。</p><div class="actions"><button class="primary" data-do="saveAuto">儲存並開始</button>${S.auto.enabled?'<button data-do="stopAuto">停止狩獵</button>':'<button data-do="saveAutoOnly">只儲存設定</button>'}</div>`)}
function showShop(){show('shop',heading('城鎮補給')+`<p>持有 ${S.player.gold.toLocaleString()} 金幣</p>${Object.values(ITEMS).filter(i=>i.price&&['potion','food','supply'].includes(i.kind)).map(i=>`<div class="item"><div class="desc"><strong>${i.name}</strong><small>${i.heal?'恢復 '+i.heal+' HP':i.mana?'恢復 '+i.mana+' MP':i.kind==='food'?'馴養食物':'自動復活倒下的寵物'} · ${i.price} 金幣 / 個 · 重量 ${i.weight}<br>持有 ${S.inventory.stacks[i.id]||0}</small></div><button data-buy="${i.id}" data-count="1" ${S.player.gold<i.price?'disabled':''}>買 1</button><button data-buy="${i.id}" data-count="5" ${S.player.gold<i.price*5?'disabled':''}>買 5</button></div>`).join('')}<div class="actions"><button data-do="heal">免費恢復生命與魔力</button><button data-panel="auto">自動補給設定</button></div>`)}
function showBank(tab=bankTab){bankTab=tab;const bag=tab==='bag'?S.inventory:S.storage,verb=tab==='bag'?'存入':'取出';show('bank',heading('倉庫')+`<div class="tabs"><button data-bank="bag" class="${tab==='bag'?'active':''}">行囊</button><button data-bank="stored" class="${tab==='stored'?'active':''}">倉庫</button></div><p class="fine">只會移動物品，不出售、不融合、不摧毀。裝備中與專屬項圈不能存放。</p>${Object.entries(bag.stacks).map(([id,n])=>`<div class="item"><div class="desc"><strong>${escape(ITEMS[id].name)} × ${n}</strong></div><button data-transfer-item="${id}" data-transfer-type="${tab==='bag'?'store':'withdraw'}">${verb}全部</button></div>`).join('')}${bag.equipment.map(e=>`<div class="item"><div class="desc"><strong>${escape(itemName(e))} × ${e.count||1}</strong></div><button data-transfer-uid="${escape(e.uid)}" data-transfer-type="${tab==='bag'?'store':'withdraw'}" ${Object.values(S.equipped).includes(e.uid)||ITEMS[e.itemId].kind==='collar'?'disabled':''}>${verb}</button></div>`).join('')||'<p class="empty">這裡沒有裝備。</p>'}<div class="actions"><button data-do="storeLoot">安全存放所有戰利品</button></div>`)}
function showSettings(){show('settings',heading('誓約之書')+`<p>${escape(S.player.name)} · ${CLASSES[S.player.classId].name} Lv.${S.player.level}</p><div class="actions"><button data-do="export">匯出備份</button><button data-do="import">匯入備份</button></div><div class="actions"><button data-do="guide">冒險指南</button><button data-do="sound">音樂／音效 ${sound?'開啟':'關閉'}</button></div><div class="actions">${legacy?'<button data-do="legacy">舊版角色與備份</button>':''}<button data-do="new">新角色</button><button data-do="archives">本機封存</button></div><div class="notice">存檔只存在此瀏覽器；換手機需手動匯出／匯入。沒有雲端同步。清除網站資料可能失去進度，請保留備份。</div><p class="fine">七日戰線 2 · 經典風格的原創單人冒險<br>戰鬥、掉落與融合成功率目前使用測試調整值，並非所有數字都經天堂經典版考證。</p>`)}
async function showArchives(){try{const entries=await listArchives();show('archives',heading('本機封存進度')+`<p>新角色與匯入前的原進度保留在這裡。先匯出檔案，再透過「匯入備份」恢復。</p>${entries.length?entries.map(e=>`<div class="item"><div class="desc"><strong>${escape(e.state.player.name)} · Lv.${e.state.player.level}</strong><small>存檔版本 ${e.revision}</small></div><button data-archive="${e.revision}">匯出</button></div>`).join(''):'<p class="empty">尚無封存角色。</p>'}`)}catch(e){toast('無法讀取封存：'+e.message)}}
function showGuide(){show('guide',heading('冒險指南')+`<h3>從普通攻擊開始</h3><p>點地面移動，點怪物靠近並攻擊。四職業都沒有起始技能；怪物會掉落技能書，打開技能選單親自閱讀。</p><h3>自動狩獵</h3><p>選地圖與藥水種類／數量。角色會狩獵、補血、整理戰利品，死亡後回城補給再返回；無法負擔補給時停止。離線計算沒有時間上限，使用同一套戰鬥與消耗規則。</p><h3>負重與融合</h3><p>藥水、物品、裝備都計算重量。重量會降低自然 HP／MP 恢復，實際門檻顯示在角色選單。兩件相同本體與 +N 的裝備才可融合；失敗兩件皆消失。自動狩獵絕不自行融合或出售。</p><h3>寵物</h3><p>點森林的野生動物餵食。野狼愛鮮肉、哈士奇愛鮮魚、杜賓犬愛肉骨。項圈對應唯一個體，保留隨機資質與等級。出戰上限為魅力除以 6 向下取整，妖精再加 2。</p><h3>經典設定與測試數值</h3><p>創角基礎、自由點數與上限依確認的資料；51 級開始，每級給 1 點。實作中的攻防、技能數值、掉率、捕捉率、負重門檻與融合曲線仍為測試設定。自訂融合、無上限離線與寵物資質優先於歷史規則。</p><p class="fine">建議橫向遊玩，可看到更完整的戰場。離線是重新開啟時計算，並非關閉瀏覽器後仍有伺服器運行。修改裝置時間或回復舊備份無法由本機遊戲徹底防止。</p>`)}
function showLegacy(){let old;try{old=JSON.parse(legacy)}catch{}show('legacy',heading('舊版角色（唯讀）')+`<p>${escape(old?.name||'舊版角色')} · ${escape(({knight:'騎士',elf:'妖精',mage:'法師',royal:'王族',darkelf:'黑暗妖精'})[old?.classId]||old?.classId||'未知職業')} · Lv.${escape(old?.level||'?')}</p><div class="notice">舊版原文已保留，沒有轉職、重配點或清除物品。新版只提供四職業；王族仍可在這裡檢視並匯出。</div><p>${escape(old?.gold??'?')} 金幣 · 裝備 ${Array.isArray(old?.inventory)?old.inventory.length:'?'} 件</p><div class="actions"><button class="primary" data-do="exportLegacy">匯出舊版原始備份</button><button data-do="new">建立獨立新冒險</button></div>`)}
function download(text,name){let blob=new Blob([text],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000)}
async function exportGame(){if(!S)return;try{if(!busy)await queueSave();let text=JSON.stringify({format:'ashen-covenant-v2',exportedAt:new Date().toISOString(),state:S},null,2);download(text,'七日戰線-'+S.player.name+'-Lv'+S.player.level+'.json');show('export',heading('保存備份')+`<p>請把下載的 JSON 檔保存到「檔案」或你自己的雲端硬碟。另一支手機可匯入這份進度。</p><textarea class="backup" readonly aria-label="備份文字">${escape(text)}</textarea><div class="actions"><button data-do="copy">複製完整備份</button><button data-do="close">完成</button></div>`)}catch(e){fatal(e)}}
function panels(name){if(!S||loading||busy)return;({bag:showBag,skills:showSkills,pets:showPets,map:showMap,settings:showSettings,auto:showAuto,character:showCharacter,shop:showShop,bank:showBank})[name]?.()}
function talk(n){if(n==='shop')showShop();if(n==='storage')showBank();if(n==='pet')showPets()}
async function prepareOffline(env){
if(modal.open)modal.close();mode='';
S=checked(env.state);revision=env.revision;resolvedAt=env.resolvedAt;
if(S.fusion.pending){const r=command(S,{type:'fuseCommit',transactionId:S.fusion.pending.id});if(!r.ok)throw Error(r.error);await queueSave(S,resolvedAt)}
const originalStart=resolvedAt,before=summarize(S);let end=Date.now(),seconds=Math.max(0,(end-resolvedAt)/1000);
if(!S.auto.enabled||seconds<1){await queueSave(S,end);return null}
const pauseBtn=$('#pauseOffline');pauseBtn.hidden=false;$('#offlinePauseNote').hidden=false;loadText('計算離線狩獵… 0%',0);
return new Promise((resolve,reject)=>{
 let generation=0,paused=false,commits=Promise.resolve();
 const fail=e=>{generation++;offlineWorker?.terminate();offlineWorker=null;pauseBtn.hidden=true;$('#offlinePauseNote').hidden=true;reject(e)};
 async function run(){
  const mine=++generation;paused=false;pauseBtn.textContent='暫停計算';pauseBtn.disabled=false;
  try{await commits;if(mine!==generation)return;const current=await readSave();if(mine!==generation)return;if(!current)throw Error('找不到離線計算的存檔');S=checked(current.state);revision=current.revision;resolvedAt=current.resolvedAt;end=Date.now();let base=resolvedAt,total=Math.max(0,(end-base)/1000);const worker=new Worker('offline-worker.mjs',{type:'module'});offlineWorker=worker;
   worker.onerror=e=>{if(mine===generation)fail(Error(e.message||'離線計算中斷'))};
   worker.onmessage=({data:d})=>{
    if(mine!==generation)return;if(d.type==='error')return fail(Error(d.message));
    if(d.type==='checkpoint'||d.type==='done'){
     let next;try{next=checked(d.state)}catch(e){return fail(e)}
     const at=base+d.processed*1000;
     commits=commits.then(async()=>{if(mine!==generation&& !paused)return;const saved=await queueSave(next,at);S=next;resolvedAt=saved.resolvedAt;revision=saved.revision;});
     commits.catch(fail);loadText(`計算離線狩獵… ${Math.floor(d.processed/Math.max(1,d.total)*100)}%`,d.processed/Math.max(1,d.total));
     if(d.type==='done'){worker.terminate();offlineWorker=null;pauseBtn.disabled=true;commits.then(()=>{if(mine!==generation)return;const tail=Math.max(0,(Date.now()-resolvedAt)/1000);if(tail>1){run();return}const at=Date.now();advance(S,Math.max(0,(at-resolvedAt)/1000),{offline:true});queueSave(S,at).then(()=>{if(mine!==generation)return;pauseBtn.hidden=true;$('#offlinePauseNote').hidden=true;resolve({before,after:summarize(S),seconds:Math.max(0,(at-originalStart)/1000)})}).catch(fail)}).catch(fail)}
    }
   };worker.postMessage({type:'simulate',state:S,seconds:total});
  }catch(e){fail(e)}
 }
 pauseBtn.onclick=async()=>{if(paused){run();return}paused=true;generation++;offlineWorker?.terminate();offlineWorker=null;pauseBtn.disabled=true;loadText('正在保存已結算進度…');try{await commits;pauseBtn.disabled=false;pauseBtn.textContent='繼續計算';loadText('已暫停，尚未結算的時間完整保留。')}catch(e){fail(e)}};
 run();
});
}
function showOffline(r){let a=r.after,b=r.before,hours=r.seconds/3600;show('offline',heading('旅途仍在繼續')+`<p>離線 ${hours>=1?hours.toFixed(1)+' 小時':Math.floor(r.seconds/60)+' 分鐘'}，依存檔裝備與設定地圖完成計算。</p><div class="stats">${[['擊敗怪物',a.kills-b.kills],['獲得經驗',Math.round(a.xpEarned-b.xpEarned)],['金幣淨變化',a.gold-b.gold],['消耗藥水',a.potionsUsed-b.potionsUsed],['死亡回城',a.deaths-b.deaths],['技能書',a.books-b.books]].map(([k,v])=>`<div class="stat"><small>${k}</small><b>${Number(v).toLocaleString()}</b></div>`).join('')}</div><p>${S.auto.enabled?'仍在設定地圖持續狩獵。':escape(S.auto.reason||'狩獵已停止。')}</p><div class="notice">戰利品已依設定保留在行囊或倉庫。技能書未自動閱讀，裝備未自動融合。</div><button class="primary" data-do="close" style="width:100%">繼續冒險</button>`)}
async function boot(){try{session=await acquireSession();if(!session.owned)throw Error('另一個分頁正在遊玩。請關閉它，再重新載入這個分頁。');const [_,old,env]=await Promise.all([renderer.load(),readLegacy(),readSave()]);ready=true;legacy=old;let report=null;if(env)report=await prepareOffline(env);finishLoading();if(S){update();if(report)showOffline(report)}else{allocation={};showStart()}}catch(e){fatal(e)}}
async function createNew(){const name=$('#nameInput')?.value||'旅人';if(S){show('replaceNew',heading('保留舊進度，開始新旅程？')+`<p>目前角色將封存在此瀏覽器的備份記錄；仍建議先匯出可攜備份。舊版角色另外保留。</p><div class="actions"><button data-do="export">先匯出</button><button class="danger" data-do="confirmNew">開始新角色</button><button data-do="new">取消</button></div>`);body.dataset.newName=name;return}await doCreate(name)}
async function doCreate(name){busy=true;try{let next=createGame(selectedClass,name,allocation,(Date.now()^Math.floor(Math.random()*0xffffffff))>>>0);checked(next);await queueSave(next,Date.now(),!!S);S=next;finishLoading();modal.close();mode='';messages([{type:'info',message:'先向商人補給，再選一張地圖出發。'}]);update()}catch(e){fatal(e)}finally{if(!recoveryError)busy=false}}
async function saveAuto(start){let settings={hpPotion:$('#hpType').value,mpPotion:$('#mpType').value,hpTarget:Number($('#hpTarget').value),mpTarget:Number($('#mpTarget').value),hpThreshold:Number($('#hpThreshold').value)/100,mpThreshold:Number($('#mpThreshold').value)/100,autoStore:$('#autoStore').checked,useSkills:$('#useSkills').checked},mapId=$('#autoMap').value;let r=await mutate({type:'configureAuto',settings,mapId});if(!r?.ok)return;if(start){r=await mutate({type:'toggleAuto',enabled:true,mapId});if(r?.ok){close();toast('自動狩獵已開始。關閉後仍會計算離線收益。')}}else{showAuto();toast('設定已儲存。')}}
function presentImport(){if(loading||recoveryError)return;if(importLegacyPending){legacy=importLegacyPending;importLegacyPending=null;showLegacy();return}const st=importPending;if(!st)return;show('importConfirm',heading('匯入這位旅人？')+`<p>${escape(st.player.name)} · ${CLASSES[st.player.classId].name} Lv.${st.player.level}</p><div class="notice warn">這份進度將成為目前角色；現有角色會先封存。匯入時不會追溯備份檔建立以來的離線獎勵。</div><div class="actions"><button class="primary" data-do="commitImport">確認匯入</button><button data-do="cancelImport">取消</button></div>`)}
async function importFile(file){const generation=++importGeneration;importPending=null;importLegacyPending=null;if(!file||busy||recoveryError)return;if(file.size>10*1024*1024)return toast('備份過大，無法安全讀取。');try{let raw=await file.text();if(generation!==importGeneration)return;let v=JSON.parse(raw);if(v.version===1){importLegacyPending=raw;presentImport();return}let st=structuredClone(checked(v.state||v));if(st.fusion.pending){let r=command(st,{type:'fuseCommit',transactionId:st.fusion.pending.id});if(!r.ok)throw Error(r.error);checked(st)}importPending=st;presentImport()}catch(e){if(generation===importGeneration)toast('無法匯入：'+e.message)}}
$('#importFile').addEventListener('cancel',cancelImport);
$('#importFile').onchange=e=>{let f=e.target.files[0];e.target.value='';importFile(f)};
body.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b||b.disabled||loading)return;const d=b.dataset;if(busy&&!(recoveryError&&['export','reload','copy','close'].includes(d.do)))return;if(d.archive){const entries=await listArchives(),entry=entries.find(x=>String(x.revision)===d.archive);if(entry){download(JSON.stringify({format:'ashen-covenant-v2',state:entry.state},null,2),'七日戰線-封存-'+entry.state.player.name+'.json');toast('已匯出封存進度，可用匯入備份載入。')}return}if(d.panel)return panels(d.panel);if(d.class){let n=$('#nameInput')?.value;selectedClass=d.class;allocation={};showStart();$('#nameInput').value=n||'';return}if(d.attr){let n=$('#nameInput')?.value;allocation[d.attr]=(allocation[d.attr]||0)+Number(d.delta);showStart();$('#nameInput').value=n||'';return}if(d.grow){await mutate({type:'allocate',attr:d.grow,count:1});showCharacter();return}if(d.bag)return showBag(d.bag);if(d.bank)return showBank(d.bank);if(d.equip){const it=S.inventory.equipment.find(x=>x.uid===d.equip),slot=it?ITEMS[it.itemId].slot:null;if(!it)return;await mutate(S.equipped[slot]===it.uid?{type:'unequip',slot}:{type:'equip',uid:it.uid});showBag();return}if(d.fuse)return showFusion(d.fuse);if(d.getBook){if(S.player.map!=='town'){await mutate({type:'travel',mapId:'town'});toast('已回城，請再點取出技能書。')}else{await mutate({type:'withdraw',itemId:'book_'+d.getBook,count:1});toast('技能書已取出，請按閱讀學習。')}showSkills();return}if(d.learn){let r=await mutate({type:'learn',skillId:d.learn});if(r?.ok)toast('技能已學會。');mode==='bag'?showBag('supplies'):showSkills();return}if(d.pet){let p=S.pets.find(p=>p.id===d.pet);await mutate({type:'petActive',petId:p.id,active:!p.active});showPets();return}if(d.revive){await mutate({type:'petRecall',petId:d.revive});showPets();return}if(d.feed){let r=await mutate({type:'feed',wildId:d.feed,itemId:d.food});if(r?.events.some(x=>x.type==='capture'))showPets();else showFeed(d.feed);return}if(d.travel){let r=await mutate({type:'travel',mapId:d.travel});if(r?.ok)close();return}if(d.buy){await mutate({type:'buy',itemId:d.buy,count:Number(d.count)});showShop();return}if(d.transferItem){await mutate({type:d.transferType,itemId:d.transferItem});showBank();return}if(d.transferUid){await mutate({type:d.transferType,uid:d.transferUid});showBank();return}switch(d.do){case'close':case'continue':close();break;case'recommend':{let n=$('#nameInput')?.value;allocation=defaultAllocation(selectedClass);showStart();$('#nameInput').value=n||'';break}case'create':await createNew();break;case'confirmNew':await doCreate(body.dataset.newName||'旅人');break;case'new':allocation={};showStart();break;case'commitFusion':await commitFusion();break;case'saveAuto':await saveAuto(true);break;case'saveAutoOnly':await saveAuto(false);break;case'stopAuto':await mutate({type:'toggleAuto',enabled:false});showAuto();break;case'heal':await mutate({type:'heal'});showShop();break;case'storeLoot':await mutate({type:'store',allLoot:true});showBank();break;case'export':await exportGame();break;case'import':cancelImport();$('#importFile').click();break;case'commitImport':{if(!importPending)return;const imported=importPending;cancelImport();busy=true;try{await queueSave(imported,Date.now(),!!S);S=imported;if(S.fusion.pending){let r=command(S,{type:'fuseCommit',transactionId:S.fusion.pending.id});if(!r.ok)throw Error(r.error);await queueSave()}busy=false;close();update();toast('備份已載入。')}catch(err){fatal(err)}break}case'cancelImport':cancelImport();S?showSettings():showStart();break;case'copy':try{await navigator.clipboard.writeText($('.backup').value);toast('已複製備份。')}catch{toast('請長按文字區域，選取並複製全部內容。')}break;case'legacy':showLegacy();break;case'archives':await showArchives();break;case'exportLegacy':download(legacy,'七日戰線-v1-原始備份.json');break;case'guide':showGuide();break;case'sound':sound=!sound;if(sound)tone(400,.2);showSettings();break;case'reload':location.reload();break}});
$$('[data-panel]').forEach(b=>b.addEventListener('click',()=>panels(b.dataset.panel)));$('#portrait').onclick=()=>panels('character');$('#autoState').onclick=()=>S&&showAuto();$('#interact').onclick=()=>talk($('#interact').dataset.npc);
$$('[data-action]').forEach(b=>b.onclick=async()=>{let a=b.dataset.action;if(a==='hp'||a==='mp'){let r=await mutate({type:'potion',itemId:S.auto.settings[a==='hp'?'hpPotion':'mpPotion']});if(r?.ok)tone(430,.2)}else if(a==='recall')await mutate({type:'travel',mapId:'town'});else{let i=Number(a.slice(-1)),k=Object.values(SKILLS).filter(k=>k.classId===S.player.classId)[i];if(k)await mutate({type:'skill',skillId:k.id})}});
$('#world').addEventListener('pointerdown',e=>{tap={x:e.clientX,y:e.clientY};$('#world').setPointerCapture(e.pointerId)});$('#world').addEventListener('pointerup',async e=>{if(!tap)return;let d=Math.hypot(e.clientX-tap.x,e.clientY-tap.y);tap=null;if(d>20||!S||busy||loading||modal.open)return;let r=$('#world').getBoundingClientRect(),hit=renderer.hitTest(S,e.clientX-r.left,e.clientY-r.top);if(hit.kind==='monster'){await mutate({type:'attack',targetId:hit.entity.id})}else if(hit.kind==='wild'){if(distance(S.player,hit.entity)>180){await mutate({type:'move',x:hit.entity.x,y:hit.entity.y+45});pendingNPC={kind:'wild',id:hit.entity.id}}else showFeed(hit.entity.id)}else if(hit.kind==='npc'){if(distance(S.player,hit.entity)>170){await mutate({type:'move',x:hit.entity.x,y:hit.entity.y+50});pendingNPC={kind:'npc',id:hit.entity.id}}else talk(hit.entity.id)}else{pendingNPC=null;await mutate({type:'move',x:hit.x,y:hit.y})}});
function syncViewport(){const v=window.visualViewport;document.documentElement?.style.setProperty('--visual-height',(v?.height||window.innerHeight)+'px');document.documentElement?.style.setProperty('--visual-top',(v?.offsetTop||0)+'px');renderer.resize()}
window.addEventListener('resize',syncViewport);window.visualViewport?.addEventListener('resize',syncViewport);window.visualViewport?.addEventListener('scroll',syncViewport);syncViewport();document.addEventListener('keydown',e=>{if(e.target.matches('input,textarea,select')||modal.open||!S)return;if(e.key==='Escape')showSettings();if(e.key.toLowerCase()==='i')showBag();if(e.key==='1')$('[data-action="hp"]').click();if(e.key==='2')$('[data-action="mp"]').click();if(['3','4','5'].includes(e.key))$(`[data-action="skill${Number(e.key)-3}"]`).click()});
let resumePending=false;
async function resumeVisible(){if(resumePending||!S||document.hidden||loading||recoveryError)return;resumePending=true;loading=true;loadText('讀取離開期間的進度…');try{while(busy&&!recoveryError)await new Promise(r=>setTimeout(r,10));if(recoveryError)return;await saveQueue;let env=await readSave();const r=await prepareOffline(env);finishLoading();update();if(r)showOffline(r)}catch(e){fatal(e)}finally{resumePending=false}}
document.addEventListener('visibilitychange',()=>{if(document.hidden){background=true;lastFrame=0;if(S&&!loading&&!busy)queueSave().catch(fatal);audio?.suspend()}else if(background&&S&&!loading){resumeVisible()}});
window.addEventListener('pagehide',()=>{if(S&&!loading&&!busy)queueSave().catch(()=>{})});
function frame(t){requestAnimationFrame(frame);if(ready)renderer.draw(S,t);if(toastUntil&&t>toastUntil){$('#toast').classList.remove('show');toastUntil=0}if(!S||busy||loading||background||mode==='blocked'){lastFrame=0;return}let dt=lastFrame?Math.min((t-lastFrame)/1000,.5):0;lastFrame=t;if(dt){let r=advance(S,dt);if(r.events.length)messages(r.events)}if(pendingNPC){let n=pendingNPC.kind==='npc'?MAPS.town.npcs.find(n=>n.id===pendingNPC.id):S.world.wildPets.find(n=>n.id===pendingNPC.id);if(!n)pendingNPC=null;else if(distance(S.player,n)<145){let q=pendingNPC;pendingNPC=null;q.kind==='npc'?talk(q.id):showFeed(q.id)}}if(t-lastUi>120){lastUi=t;update()}if(t-lastSave>2000){lastSave=t;queueSave().catch(fatal)}}
requestAnimationFrame(frame);boot();
