if(document.modelContext?.registerTool)try{Promise.resolve(document.modelContext.registerTool({name:'read_adventure_status',title:'讀取冒險狀態',description:'Read character, hunt settings, equipment, pet and local-save state without advancing or changing the game.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(input&&Object.keys(input).length)throw Error('No parameters accepted');return S?{name:S.player.name,class:CLASSES[S.player.classId].name,...summarize(S),revision,skills:S.player.skills.map(k=>SKILLS[k].name)}:{active:false}}})).catch(()=>{})}catch{}
